insert into hr_onboarding_operation_log (
    onboarding_id, operation_type, from_status, to_status, operator_user_id,
    operator_name, changed_field_keys, decision_summary, operation_summary,
    operation_time, create_by, update_by, remark
) values (
    #{onboardingId}, #{operationType}, #{fromStatus}, #{toStatus}, #{operatorUserId},
    #{operatorName}, #{changedFieldKeys}, #{decisionSummary}, #{operationSummary},
    coalesce(#{operationTime}, sysdate()), #{createBy}, #{updateBy}, #{remark}
)
